mapper.select:
SELECT id, task_type, display_name, handler_ref, max_attempts, timeout_seconds,
       status, created_at, updated_at
FROM ainer_task_definition WHERE task_type = #{taskType}

mapper.update:
UPDATE ainer_task_definition
SET status = #{status}, updated_at = #{now}
WHERE task_type = #{taskType}

mapper.select:
SELECT id, task_type, payload::text AS payload, status, attempt_count, max_attempts,
       next_run_at, interval_seconds, locked_by, locked_at, last_error,
       created_by_issuer, created_by_type, created_by_id,
       created_at, updated_at, completed_at
FROM ainer_task_job

    status = #{status}

        AND
        task_type = #{taskType}


ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM ainer_task_job

    status = #{status}

        AND
        task_type = #{taskType}

mapper.update:
UPDATE ainer_task_job
SET status = 'CANCELLED', completed_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING'

UPDATE ainer_task_job
SET status = 'PENDING', next_run_at = #{nextRunAt}, updated_at = #{now}
WHERE id = #{id} AND status IN ('FAILED', 'EXHAUSTED')
